import { useEffect, useRef } from "react";
import * as THREE from "three";

/**
 * A slow stream of comic panels in 3D. Pages are generated by recursively splitting a rectangle
 * (the way a page layout is cut into panels), then scrolled upward like a webtoon strip.
 * Palette comes from the Sutrid tokens. Pointer tilts the field and moves two coloured lights.
 */

const PALETTE = ["#ff795e", "#51d0b0", "#f0c65b", "#6ab8ef", "#a4d76a", "#f092ad"];
const COVER_COLS = 10;
const COVER_ROWS = 10;
const COVER_W = 112;
const COVER_H = 168;
/** Small WebP copies of the bundled covers (see scripts/make-cover-thumbs.mjs), about 8 KB each. */
const COVER_DIR = "/assets/webtoon-covers/thumbs";
const COVER_PARALLEL = 8;
const INK = new THREE.Color("#111713");

interface Rect { x: number; y: number; w: number; h: number }

function splitPage(r: Rect, depth: number, rnd: () => number, out: Rect[]) {
  const gutter = 0.1;
  if (depth === 0 || (depth < 3 && rnd() < 0.18)) {
    out.push(r);
    return;
  }
  const vertical = r.w / r.h > 0.9 ? rnd() < 0.8 : rnd() < 0.2;
  const t = 0.35 + rnd() * 0.3;
  if (vertical) {
    const w1 = r.w * t - gutter / 2;
    splitPage({ x: r.x, y: r.y, w: w1, h: r.h }, depth - 1, rnd, out);
    splitPage({ x: r.x + w1 + gutter, y: r.y, w: r.w - w1 - gutter, h: r.h }, depth - 1, rnd, out);
  } else {
    const h1 = r.h * t - gutter / 2;
    splitPage({ x: r.x, y: r.y, w: r.w, h: h1 }, depth - 1, rnd, out);
    splitPage({ x: r.x, y: r.y + h1 + gutter, w: r.w, h: r.h - h1 - gutter }, depth - 1, rnd, out);
  }
}

function mulberry(seed: number) {
  return () => {
    seed |= 0;
    seed = (seed + 0x6d2b79f5) | 0;
    let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function createCoverAtlas(seed: number) {
  const canvas = document.createElement("canvas");
  canvas.width = COVER_COLS * COVER_W;
  canvas.height = COVER_ROWS * COVER_H;
  const context = canvas.getContext("2d");
  if (!context) throw new Error("Could not create cover artwork");

  const random = mulberry(seed);
  const firstWords = ["After", "Small", "Paper", "Hidden", "Bright", "Quiet", "Last", "Wild", "Open", "Blue"];
  const secondWords = ["Orbit", "Garden", "Signal", "Season", "Lantern", "Current", "Archive", "Summer", "Comet", "Window"];

  for (let index = 0; index < COVER_COLS * COVER_ROWS; index++) {
    const x = (index % COVER_COLS) * COVER_W;
    const y = Math.floor(index / COVER_COLS) * COVER_H;
    const accent = PALETTE[Math.floor(random() * PALETTE.length)]!;
    const dark = random() > 0.55;
    const base = dark ? "#17201b" : "#d9e1d7";
    const ink = dark ? "#f4f6ef" : "#17201b";
    const gradient = context.createLinearGradient(x, y, x + COVER_W, y + COVER_H);
    gradient.addColorStop(0, base);
    gradient.addColorStop(1, dark ? "#29342c" : "#bac9bd");
    context.fillStyle = gradient;
    context.fillRect(x, y, COVER_W, COVER_H);

    context.save();
    context.beginPath();
    context.rect(x, y, COVER_W, COVER_H);
    context.clip();
    for (let shape = 0; shape < 8; shape++) {
      const sx = x + random() * COVER_W;
      const sy = y + random() * COVER_H;
      const size = 12 + random() * 68;
      context.globalAlpha = 0.16 + random() * 0.42;
      context.fillStyle = shape % 2 ? accent : ink;
      if (shape % 3 === 0) {
        context.beginPath();
        context.arc(sx, sy, size / 2, 0, Math.PI * 2);
        context.fill();
      } else if (shape % 3 === 1) {
        context.save();
        context.translate(sx, sy);
        context.rotate((random() - 0.5) * 1.2);
        context.fillRect(-size / 2, -size / 8, size, size / 4);
        context.restore();
      } else {
        context.beginPath();
        context.moveTo(sx, sy);
        context.lineTo(sx + size * 0.55, sy - size);
        context.lineTo(sx + size, sy + size * 0.2);
        context.closePath();
        context.fill();
      }
    }
    context.globalAlpha = 0.95;
    context.fillStyle = ink;
    context.fillRect(x + 8, y + COVER_H - 59, COVER_W - 16, 49);
    context.fillStyle = accent;
    context.font = "700 6px sans-serif";
    context.fillText("COMIK ORIGINAL", x + 13, y + COVER_H - 45);
    context.fillStyle = dark ? "#f4f6ef" : "#17201b";
    context.font = "900 13px sans-serif";
    context.fillText(firstWords[index % firstWords.length]!, x + 13, y + COVER_H - 27);
    context.fillText(secondWords[Math.floor(index / firstWords.length)]!, x + 13, y + COVER_H - 14);
    context.restore();
  }

  const texture = new THREE.CanvasTexture(canvas);
  texture.colorSpace = THREE.SRGBColorSpace;
  texture.anisotropy = Math.min(4, 8);
  return { texture, canvas };
}

interface BundledCover { file: string }
let coverManifest: Promise<BundledCover[]> | null = null;

function getBundledCovers(): Promise<BundledCover[]> {
  if (!coverManifest) {
    coverManifest = fetch(`${COVER_DIR}/manifest.json`)
      .then((response) => {
        if (!response.ok) throw new Error("Could not load cover list");
        return response.json() as Promise<BundledCover[]>;
      })
      .catch((error) => {
        coverManifest = null;
        throw error;
      });
  }
  return coverManifest;
}

function loadBundledCovers(canvas: HTMLCanvasElement, texture: THREE.CanvasTexture, seed: number) {
  let stopped = false;
  let cursor = 0;
  let active = 0;
  const images: HTMLImageElement[] = [];
  const context = canvas.getContext("2d");
  if (!context) return () => {};
  const random = mulberry(seed ^ 0x5f3759df);
  let urls: string[] = [];

  void getBundledCovers().then((covers) => {
    if (stopped) return;
    const shuffled = covers.map((cover) => cover.file);
    for (let index = shuffled.length - 1; index > 0; index--) {
      const swap = Math.floor(random() * (index + 1));
      [shuffled[index], shuffled[swap]] = [shuffled[swap]!, shuffled[index]!];
    }
    urls = shuffled.slice(0, COVER_COLS * COVER_ROWS).map((file) => `${COVER_DIR}/${encodeURIComponent(file)}`);
    pump();
  }).catch(() => {});

  // Uploading the whole 1120x1680 canvas to the GPU per image is costly, so coalesce uploads.
  let uploadTimer = 0;
  const scheduleUpload = () => {
    if (uploadTimer) return;
    uploadTimer = window.setTimeout(() => {
      uploadTimer = 0;
      texture.needsUpdate = true;
    }, 120);
  };

  const finish = (image: HTMLImageElement, index: number) => {
    active--;
    if (!stopped && image.naturalWidth > 0) {
      const x = (index % COVER_COLS) * COVER_W;
      const y = Math.floor(index / COVER_COLS) * COVER_H;
      const scale = Math.max(COVER_W / image.naturalWidth, COVER_H / image.naturalHeight);
      const width = image.naturalWidth * scale;
      const height = image.naturalHeight * scale;
      context.save();
      context.beginPath();
      context.rect(x, y, COVER_W, COVER_H);
      context.clip();
      context.drawImage(image, x + (COVER_W - width) / 2, y + (COVER_H - height) / 2, width, height);
      context.globalAlpha = 0.18;
      context.fillStyle = PALETTE[index % PALETTE.length]!;
      context.fillRect(x, y, COVER_W, COVER_H);
      context.restore();
      scheduleUpload();
    }
    pump();
  };

  const pump = () => {
    while (!stopped && active < COVER_PARALLEL && cursor < urls.length) {
      const index = cursor++;
      const image = new Image();
      images.push(image);
      image.onload = () => finish(image, index);
      image.onerror = () => finish(image, index);
      active++;
      image.src = urls[index]!;
    }
  };
  pump();
  return () => {
    stopped = true;
    window.clearTimeout(uploadTimer);
    for (const image of images) {
      image.onload = null;
      image.onerror = null;
      image.src = "";
    }
  };
}

export function PanelField({ mode = "hero", className }: { mode?: "bg" | "hero"; className?: string }) {
  const ref = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    // The scene starts once the page has drawn and the browser is idle, so it never delays the first paint or the library.
    let stop: (() => void) | undefined;
    const start = () => { stop = boot(); };
    const idle = "requestIdleCallback" in window;
    const handle = idle ? window.requestIdleCallback(start, { timeout: 2500 }) : window.setTimeout(start, 700);
    return () => {
      if (idle) window.cancelIdleCallback(handle); else window.clearTimeout(handle);
      stop?.();
    };

    function boot(): (() => void) | undefined {
    const canvas = ref.current;
    if (!canvas) return;
    const reduce = matchMedia("(prefers-reduced-motion: reduce)").matches;
    const bg = mode === "bg";

    let renderer: THREE.WebGLRenderer;
    try {
      renderer = new THREE.WebGLRenderer({ canvas, antialias: !bg, alpha: true, powerPreference: "low-power" });
    } catch {
      return; // no WebGL, the CSS grid still carries the look
    }
    // Software rendering (no GPU) would make this decoration the slowest thing on the page, so it is skipped there.
    const gl = renderer.getContext();
    const debug = gl.getExtension("WEBGL_debug_renderer_info");
    if (debug && /swiftshader|llvmpipe|software|basic render/i.test(String(gl.getParameter(debug.UNMASKED_RENDERER_WEBGL)))) {
      renderer.dispose();
      return;
    }
    renderer.setPixelRatio(Math.min(devicePixelRatio, bg ? 0.75 : 1.75));
    renderer.setClearColor(0x000000, 0);

    const scene = new THREE.Scene();
    const camera = new THREE.PerspectiveCamera(42, 1, 0.1, 100);
    camera.position.set(0, 0, bg ? 26 : 15);

    scene.add(new THREE.AmbientLight(0xffffff, 0.8));
    const key = new THREE.DirectionalLight(0xffffff, 1.1);
    key.position.set(-4, 6, 8);
    scene.add(key);
    const lightA = new THREE.PointLight(0x9d6cff, 70, 30);
    const lightB = new THREE.PointLight(0xfa625f, 50, 30);
    scene.add(lightA, lightB);

    const seed = Math.floor(Math.random() * 0xffffffff);
    const rnd = mulberry(seed);
    const PAGE_W = 5.6, PAGE_H = 7.8, PAGES = 4, COLS = 3;
    const rects: (Rect & { page: number; col: number })[] = [];
    for (let p = 0; p < PAGES; p++) {
      for (let c = 0; c < COLS; c++) {
        const list: Rect[] = [];
        splitPage({ x: 0, y: 0, w: PAGE_W, h: PAGE_H }, 3, rnd, list);
        list.forEach((r) => rects.push({ ...r, x: r.x + (c - (COLS - 1) / 2) * (PAGE_W + 0.5) - PAGE_W / 2, page: p, col: c }));
      }
    }

    const geo = new THREE.BoxGeometry(1, 1, 1);
    const { texture: coverTexture, canvas: coverCanvas } = createCoverAtlas(seed);
    const stopCoverLoading = loadBundledCovers(coverCanvas, coverTexture, seed);
    const sideMaterial = new THREE.MeshStandardMaterial({ color: "#ffffff", roughness: 0.65, metalness: 0.05 });
    const coverMaterial = new THREE.MeshStandardMaterial({ map: coverTexture, color: "#ffffff", roughness: 0.72, metalness: 0.02 });
    coverMaterial.onBeforeCompile = (shader) => {
      shader.vertexShader = shader.vertexShader.replace(
        "#include <common>",
        "#include <common>\nattribute float coverIndex;",
      );
      shader.vertexShader = shader.vertexShader.replace(
        "#include <uv_vertex>",
        "#include <uv_vertex>\n#ifdef USE_MAP\nfloat coverCol = mod(coverIndex, 10.0);\nfloat coverRow = 9.0 - floor(coverIndex / 10.0);\nvMapUv = (vMapUv + vec2(coverCol, coverRow)) / 10.0;\n#endif",
      );
    };
    coverMaterial.customProgramCacheKey = () => "comik-cover-atlas-v1";
    const materials = [sideMaterial, sideMaterial, sideMaterial, sideMaterial, coverMaterial, sideMaterial];
    const mesh = new THREE.InstancedMesh(geo, materials, rects.length);
    mesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
    const coverIndexes = new Float32Array(rects.length);
    const base = rects.map((_r, i) => {
      const accent = new THREE.Color(PALETTE[Math.floor(rnd() * PALETTE.length)]!);
      const c = INK.clone().lerp(accent, 0.42 + rnd() * 0.34);
      mesh.setColorAt(i, c);
      coverIndexes[i] = Math.floor(rnd() * COVER_COLS * COVER_ROWS);
      return { z: (rnd() - 0.5) * 0.9, tilt: (rnd() - 0.5) * 0.12, depth: 0.12 + rnd() * 0.18 };
    });
    geo.setAttribute("coverIndex", new THREE.InstancedBufferAttribute(coverIndexes, 1));
    const group = new THREE.Group();
    group.add(mesh);
    group.rotation.set(-0.5, 0.18, 0.2);
    scene.add(group);

    const span = PAGES * (PAGE_H + 0.5);
    const m4 = new THREE.Matrix4();
    const q = new THREE.Quaternion();
    const e = new THREE.Euler();
    const pos = new THREE.Vector3();
    const scl = new THREE.Vector3();
    const place = (t: number) => {
      for (let i = 0; i < rects.length; i++) {
        const r = rects[i]!, b = base[i]!;
        let y = r.y + r.page * (PAGE_H + 0.5) - t;
        y = ((((y + span / 2) % span) + span) % span) - span / 2;
        pos.set(r.x + r.w / 2, -(y + r.h / 2) + 1, b.z);
        e.set(0, 0, b.tilt);
        q.setFromEuler(e);
        scl.set(r.w, r.h, b.depth);
        m4.compose(pos, q, scl);
        mesh.setMatrixAt(i, m4);
      }
      mesh.instanceMatrix.needsUpdate = true;
    };
    place(0);

    const ptr = { x: 0, y: 0, tx: 0, ty: 0 };
    const onMove = (ev: PointerEvent) => {
      const rect = bg ? { left: 0, top: 0, width: innerWidth, height: innerHeight } : canvas.getBoundingClientRect();
      ptr.tx = ((ev.clientX - rect.left) / rect.width) * 2 - 1;
      ptr.ty = ((ev.clientY - rect.top) / rect.height) * 2 - 1;
    };
    addEventListener("pointermove", onMove, { passive: true });

    const resize = () => {
      const w = bg ? innerWidth : canvas.clientWidth;
      const h = bg ? innerHeight : canvas.clientHeight;
      renderer.setSize(w, h, false);
      camera.aspect = w / Math.max(h, 1);
      camera.updateProjectionMatrix();
    };
    resize();
    const ro = new ResizeObserver(resize);
    ro.observe(bg ? document.documentElement : canvas);

    let visible = true;
    const io = bg ? null : new IntersectionObserver(([en]) => (visible = !!en?.isIntersecting));
    io?.observe(canvas);

    let raf = 0, last = performance.now(), t = 0, acc = 0, lag = 0, lastFrame = performance.now();
    const frameGap = bg ? 1000 / 24 : 1000 / 60;
    // The backdrop sits under the whole page, so drawing it while the page scrolls or is being clicked competes with
    // the page itself. It rests until the pointer and scroll have been quiet for a moment.
    let quietAt = 0;
    const busy = () => { quietAt = performance.now() + 350; };
    if (bg) for (const type of ["scroll", "wheel", "touchmove", "pointerdown", "keydown"]) addEventListener(type, busy, { passive: true, capture: true });
    const speed = bg ? 0.16 : 0.32;
    const tick = (now: number) => {
      raf = requestAnimationFrame(tick);
      // A device that cannot keep this up (software rendering, a busy GPU) gets a still canvas instead of a stalled
      // page: after about 40 slow frames the animation stops. Long gaps are a hidden tab, not slowness.
      const gap = now - lastFrame;
      lastFrame = now;
      if (visible && !document.hidden) {
        if (gap > 90 && gap < 1000) lag++; else if (lag > 0) lag -= 0.25;
        if (lag >= 40) { cancelAnimationFrame(raf); raf = 0; if (bg) canvas.style.display = "none"; return; }
      }
      if (bg && now < quietAt) { last = now; return; }
      const dt = now - last;
      if (!visible || document.hidden || dt < 4) return;
      acc += dt;
      last = now;
      if (acc < frameGap) return;
      const step = Math.min(acc, 100) / 1000;
      acc = 0;
      t += step * speed;
      place(t);
      ptr.x += (ptr.tx - ptr.x) * 0.06;
      ptr.y += (ptr.ty - ptr.y) * 0.06;
      group.rotation.y = 0.18 + ptr.x * 0.16;
      group.rotation.x = -0.5 + ptr.y * 0.08;
      lightA.position.set(ptr.x * 9, -ptr.y * 6 + 2, 6);
      lightB.position.set(-ptr.x * 9, ptr.y * 6 - 2, 5);
      renderer.render(scene, camera);
    };
    const onContextLost = (event: Event) => {
      event.preventDefault();
      cancelAnimationFrame(raf);
      raf = 0;
    };
    const onContextRestored = () => {
      resize();
      place(t);
      renderer.render(scene, camera);
      last = performance.now();
      acc = 0;
      if (!reduce) raf = requestAnimationFrame(tick);
    };
    canvas.addEventListener("webglcontextlost", onContextLost);
    canvas.addEventListener("webglcontextrestored", onContextRestored);
    if (reduce) renderer.render(scene, camera);
    else raf = requestAnimationFrame(tick);

    return () => {
      cancelAnimationFrame(raf);
      if (bg) for (const type of ["scroll", "wheel", "touchmove", "pointerdown", "keydown"]) removeEventListener(type, busy, { capture: true });
      removeEventListener("pointermove", onMove);
      ro.disconnect();
      io?.disconnect();
      canvas.removeEventListener("webglcontextlost", onContextLost);
      canvas.removeEventListener("webglcontextrestored", onContextRestored);
      stopCoverLoading();
      coverTexture.dispose();
      sideMaterial.dispose();
      coverMaterial.dispose();
      geo.dispose();
      mesh.dispose();
      renderer.dispose();
    };
    }
  }, [mode]);

  return <canvas ref={ref} className={className} aria-hidden="true" />;
}
